const MAX_INPUT_LENGTH:usize=512;
const MAX_OUTPUT_BYTES:usize=512;
fn morseWord(index:usize)i64{const words=[_]i64{514,1031,1029,771,257,1037,769,1039,515,1032,770,1035,512,513,768,1033,1026,773,775,256,774,1038,772,1030,1028,1027};return words[index];}
fn separator(text:[*c]const i64,p:usize,end:usize)bool{return p+2<end and text[p]==32 and text[p+1]==124 and text[p+2]==32;}
fn decodeToken(text:[*c]const i64,start:usize,finish:usize)u8{for(0..26)|letter|{const word=morseWord(letter);const n:usize=@intCast(@divTrunc(word,256)%8);if(finish-start!=n)continue;const mask=@mod(word,32);var matches=true;for(0..n)|bit|{const shift=n-bit-1;const v=@mod(@divTrunc(mask,@as(i64,1)<<@intCast(shift)),2);const expected:i64=if(v!=0)46 else 45;if(text[start+bit]!=expected){matches=false;break;}}if(matches)return @intCast(65+letter);}return 63;}
fn appendWord(text:[*c]const i64,start:usize,finish_value:usize,out:*[MAX_OUTPUT_BYTES]u8,written:*usize)void{if(start==finish_value){out[written.*]=63;written.*+=1;return;}var finish=finish_value;while(finish>start and text[finish-1]==32)finish-=1;if(start==finish)return;var token=start;for(start..finish+1)|p|{if(p==finish){out[written.*]=decodeToken(text,token,p);written.*+=1;}else if(text[p]==32){out[written.*]=decodeToken(text,token,p);written.*+=1;token=p+1;}}}
fn decode(text:[*c]const i64,length:usize,out:*[MAX_OUTPUT_BYTES]u8)usize{if(length==0){out[0]=63;return 1;}var finish=length;while(finish>=3 and separator(text,finish-3,finish))finish-=3;if(finish==0)return 0;var written:usize=0;var start:usize=0;var p:usize=0;while(p+2<finish){if(separator(text,p,finish)){appendWord(text,start,p,out,&written);out[written]=32;written+=1;p+=3;start=p;}else p+=1;}appendWord(text,start,finish,out,&written);return written;}
export fn morse_code_converter_decode(input:[*c]const i64,length:usize,output:[*c]u8,capacity:usize)i64{if((input==null and length>0) or length>MAX_INPUT_LENGTH)return -1;for(0..length)|i|if(input[i]<0 or input[i]>127)return -1;var scratch:[MAX_OUTPUT_BYTES]u8=undefined;const written=decode(input,length,&scratch);if(output==null or capacity<written)return -2;@memcpy(output[0..written],scratch[0..written]);return @intCast(written);}
